function endDraw(e){if(!drawStart)return;drawStart=null;scene.remove(drawLine);drawLine.geometry.dispose();drawLine.material.dispose();drawLine=null;if(strokePoints.length>1){const obj=createInkStroke(strokePoints,activeInk);selectObject(obj);if(activeInk==='gravity')obj.userData.vel.y=-.6;}strokePoints=[];}

let orbitDrag=null,pinchPointers=new Map(),vehicleKeys=new Set();
canvas.addEventListener('pointerdown',e=>{if(e.button===2){orbitDrag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);e.preventDefault();return;}if(e.pointerType==='touch'){pinchPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinchPointers.size===2){drawStart=null;orbitDrag={two:true,dist:touchDistance(),mid:touchMid()};return;}}startDraw(e);});
canvas.addEventListener('pointermove',e=>{if(orbitDrag){if(orbitDrag.two&&pinchPointers.size>=2){const dist=touchDistance(),mid=touchMid();orbit.radius=THREE.MathUtils.clamp(orbit.radius+(orbitDrag.dist-dist)*.018,6,24);orbit.yaw+=(mid.x-orbitDrag.mid.x)*.006;orbit.pitch=THREE.MathUtils.clamp(orbit.pitch-(mid.y-orbitDrag.mid.y)*.006,-.25,1.05);orbitDrag={two:true,dist,mid};}else{orbit.yaw+=(e.clientX-orbitDrag.x)*.006*settings.sensitivity;orbit.pitch=THREE.MathUtils.clamp(orbit.pitch+(e.clientY-orbitDrag.y)*.005*settings.sensitivity,-.25,1.05);orbitDrag.x=e.clientX;orbitDrag.y=e.clientY;}updateCamera();return;}moveDraw(e);});
canvas.addEventListener('pointerup',e=>{if(e.pointerType==='touch'){pinchPointers.delete(e.pointerId);if(pinchPointers.size<2&&orbitDrag?.two)orbitDrag=null;}if(orbitDrag&&!orbitDrag.two){orbitDrag=null;return;}endDraw(e);});canvas.addEventListener('pointercancel',e=>{pinchPointers.delete(e.pointerId);orbitDrag=null;endDraw(e);});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function touchDistance(){const a=[...pinchPointers.values()];return a.length<2?0:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);}
function touchMid(){const a=[...pinchPointers.values()];return{x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2};}
canvas.addEventListener('wheel',e=>{e.preventDefault();setDepth(depth+e.deltaY*.004);},{passive:false});
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key>='1'&&e.key<='4')setInk(['glass','leaf','void','gravity'][Number(e.key)-1]);if(e.key.toLowerCase()==='x'){eraseMode=!eraseMode;$('#btn-erase').classList.toggle('active',eraseMode);toast(eraseMode?'Erase mode on':'Erase mode off');}if(e.key.toLowerCase()==='r'&&weapon)reloadWeapon(weapon);if(e.key==='Escape')closeModal();if(['w','a','s','d',' '].includes(e.key.toLowerCase()))vehicleKeys.add(e.key.toLowerCase());});window.addEventListener('keyup',e=>vehicleKeys.delete(e.key.toLowerCase()));
