const wait = ms => new Promise(r => setTimeout(r, ms));
const pages = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = pages.find(p => p.type === 'page' && p.url.includes('8765'));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve,reject) => { ws.onopen=resolve; ws.onerror=reject; });
let id=0; const pending=new Map(), errors=[];
ws.onmessage = e => { const m=JSON.parse(e.data); if(m.id && pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);} else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.text+': '+(m.params.exceptionDetails.exception?.description||''));} };
const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
const ev=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result?.result?.value;
const mouse=async(type,x,y,button='left',buttons=0)=>call('Input.dispatchMouseEvent',{type,x,y,button,buttons});
const drag=async(points)=>{const [a,...rest]=points;await mouse('mouseMoved',...a);await mouse('mousePressed',...a,'left',1);for(const [x,y] of rest){await mouse('mouseMoved',x,y,'left',1);await wait(35);}await mouse('mouseReleased',...rest.at(-1),'left',0);await wait(250);};
const shot=async path=>{const r=await call('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});const fs=await import('node:fs/promises');await fs.writeFile(path,Buffer.from(r.result.data,'base64'));};
await call('Runtime.enable');await call('Page.enable');await call('Page.reload',{ignoreCache:true});await wait(1800);
const checks={viewport:await ev('({w:innerWidth,h:innerHeight})')};
await ev("document.querySelector('[data-ink=leaf]').click()");await drag([[580,355],[610,348],[640,355],[670,370],[700,380]]);
await ev("document.querySelector('#selection-card').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}))");await ev("document.querySelector('[data-category=vehicle]').click()");
checks.vehicleOptions=await ev("[...document.querySelectorAll('[data-blueprint]')].map(b=>b.dataset.blueprint)");
await ev("document.querySelector('[data-blueprint=buggy]').click()");await wait(250);
checks.tune=await ev("({title:document.querySelector('.modal h2')?.textContent,toggles:[...document.querySelectorAll('[data-part]')].map(x=>[x.dataset.part,x.checked])})");
await shot('/tmp/opencode/vehicle-before.png');
await ev("document.querySelector('[data-part=seat]').click()");await wait(500);checks.seatToggle=await ev("document.querySelector('[data-part=seat]').checked");
await ev("document.querySelector('#drive-now').click();document.querySelector('[data-done]').click()");
await shot('/tmp/opencode/vehicle-drive-before.png');
await call('Input.dispatchKeyEvent',{type:'keyDown',key:'w',code:'KeyW',windowsVirtualKeyCode:87});await wait(1300);await call('Input.dispatchKeyEvent',{type:'keyUp',key:'w',code:'KeyW',windowsVirtualKeyCode:87});await wait(300);await shot('/tmp/opencode/vehicle-drive-after.png');
checks.drivingToast=await ev("document.querySelector('#toasts').innerText");
console.log(JSON.stringify({checks,errors},null,2));ws.close();

