await ev("document.querySelector('[data-ink=gravity]').click()");
await mouse('mouseMoved',510,330);await mouse('mousePressed',510,330,'left',1);
for(const [x,y] of [[535,325],[560,320],[585,315],[610,310],[635,305],[660,300]]){await mouse('mouseMoved',x,y,'left',1);await wait(60);}
await mouse('mouseReleased',660,300,'left',0);await wait(100);
const drawn=await ev("(()=>{const o=window.__linebornTest.objects.find(x=>x.userData.ink==='gravity');return o&&{name:o.userData.name,points:o.userData.points.length,positionY:o.position.y,groundY:o.userData.groundY,velocityY:o.userData.vel.y,score:document.querySelector('#score').textContent,selected:document.querySelector('#sel-name').textContent}})()");
await wait(1400);
const settled=await ev("(()=>{const o=window.__linebornTest.objects.find(x=>x.userData.ink==='gravity');return o&&{positionY:o.position.y,groundY:o.userData.groundY,velocityY:o.userData.vel.y,resting:Math.abs(o.position.y-o.userData.groundY)<.001}})()");
const shot=await call('Page.captureScreenshot',{format:'jpeg',quality:68,captureBeyondViewport:false});
const fs=await import('node:fs/promises');await fs.writeFile('/tmp/opencode/lineborn-latest.jpg',Buffer.from(shot.result.data,'base64'));
console.log(JSON.stringify({viewport,drawn,settled,errors,screenshot:'/tmp/opencode/lineborn-latest.jpg'},null,2));ws.close();

